targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		ruleId: event.payload.cell.ruleId,
		ruleType: event.payload.cell.ruleType,
		tableName: event.payload.cell.tableName
	};
})

script.inlineScript:
